local module = {}
local Audio = require(script.Audio)
module.__index = module

local DEBRIS_SERVICE = game:GetService("Debris")
local SOUND_SERVICE = game:GetService("SoundService")
local TWEEN_SERVICE = game:GetService("TweenService")
local CONTENT_PROVIDER = game:GetService("ContentProvider")

local TB_SOUND_SCRIPT = game.ReplicatedStorage._genConfigs:FindFirstChild("asset_tbsound")
local TB_SOUNDGROUP_SCRIPT = game.ReplicatedStorage._genConfigs:FindFirstChild("asset_tbsoundgroup")

local TB_SOUND_ASSETS
local TB_SOUNDGROUP_ASSETS

local WORKSPACE_ASSET_FOLDER = Instance.new("Part", workspace.Terrain)
WORKSPACE_ASSET_FOLDER.Name = "3D Audio Assets"
WORKSPACE_ASSET_FOLDER.Anchored = true
WORKSPACE_ASSET_FOLDER.CanCollide = false
WORKSPACE_ASSET_FOLDER.CanQuery = false
WORKSPACE_ASSET_FOLDER.CanTouch = false
WORKSPACE_ASSET_FOLDER.Transparency = 1
WORKSPACE_ASSET_FOLDER.Size = Vector3.new()

local SOUND_SERVICE_ASSET_FOLDER = Instance.new("Folder", workspace.Terrain)
SOUND_SERVICE_ASSET_FOLDER.Name = "Audio Assets"

local BACKGROUND_MUSIC_FADE_INTERVAL = 1

local INSTANCE = nil


local function getSoundAttachment(position)
	local soundAttachment = Instance.new("Attachment")
	soundAttachment.Name = "_sound"
	soundAttachment.WorldCFrame = CFrame.new(position)
	return soundAttachment
end

function module.new(tbSound, tbSoundGroup)
    if INSTANCE then
        return INSTANCE
    end

	if tbSound and tbSoundGroup then
		TB_SOUND_ASSETS = tbSound
		TB_SOUNDGROUP_ASSETS = tbSoundGroup
	elseif TB_SOUND_SCRIPT and TB_SOUNDGROUP_SCRIPT then
		TB_SOUND_ASSETS = require(TB_SOUND_SCRIPT)
		TB_SOUNDGROUP_ASSETS = require(TB_SOUNDGROUP_SCRIPT)
	else
		error("Audio Manager Error: Missing sound and sound group assets")
	end

    local self = setmetatable({}, module)
	self.SoundGroups = {}
	self.Audios = {}
    self.CurrentBackgroundMusic = nil
    INSTANCE = self
	self:LoadSoundGroups()
    return self
end

function module:LoadSoundGroups()
	for _, soundGroupAsset in pairs(TB_SOUNDGROUP_ASSETS) do
		local soundGroup = Instance.new("SoundGroup")
		soundGroup.Name = soundGroupAsset.Id
		soundGroup.Volume = soundGroupAsset.Volume
		soundGroup.Parent = SOUND_SERVICE
		self.SoundGroups[soundGroupAsset.Id] = soundGroup
	end
end

function module:GetAudioFromId(id)
	local audio = self.Audios[id]
	if (audio == nil) then
		local soundAsset = TB_SOUND_ASSETS[id]
		if (soundAsset == nil) then
			warn("Audio Manager Error: Invalid sound asset id", id)
		end
		audio = Audio.new(soundAsset)
		self.Audios[id] = audio
	end
	return audio
end

function module:GetAudioAssetFromId(id, recycled)
	local audio = self:GetAudioFromId(id)
	local sound = audio:GetSound()
	if recycled then
		audio:RecycleOnEnded(sound)
	end
	return sound
end

function module:GetSoundName(sound)
	return sound.Name
end

function module:Preload(soundId)
	if typeof(soundId) == "string" then
		local audio = self:GetAudioFromId(soundId)
		if audio then
			spawn(function()
				CONTENT_PROVIDER:PreloadAsync({audio:GetSoundId()})
			end)
		end
	elseif typeof(soundId) == "table" then
		for _, id in pairs(soundId) do
			local audio = self:GetAudioFromId(id)
			if audio then
				spawn(function()
					CONTENT_PROVIDER:PreloadAsync({audio:GetSoundId()})
				end)
			end
		end
	end
end

function module:SetSoundGroupVolume(soundGroupId, volume)
	local soundGroup = self.SoundGroups[soundGroupId]
	if (soundGroup == nil) then
		error("Audio Manager Error: Invalid sound group id")
	end
	soundGroup.Volume = volume
end

function module:SetBackgroundMusicFadeTime(fadeTime)
	BACKGROUND_MUSIC_FADE_INTERVAL = fadeTime or 1
end

function module:PlayBackgroundMusic(backgroundMusicId)
	local sound = self:GetAudioAssetFromId(backgroundMusicId)
	if (self.CurrentBackgroundMusic ~= nil) then
		local currentBackgroundMusicId = self:GetSoundName(self.CurrentBackgroundMusic)
		if (currentBackgroundMusicId == backgroundMusicId) then
			return
		else
			self:StopBackgroundMusic()
		end
	end
	
	local soundClone = sound:Clone()
	soundClone.Volume = 0
	soundClone.Looped = true
	soundClone.Parent = SOUND_SERVICE_ASSET_FOLDER
	soundClone:Play()
	TWEEN_SERVICE:Create(soundClone, TweenInfo.new(BACKGROUND_MUSIC_FADE_INTERVAL), {Volume = sound.Volume}):Play()
	self.CurrentBackgroundMusic = soundClone
    return soundClone
end

function module:StopBackgroundMusic()
	if (self.CurrentBackgroundMusic == nil) then
		warn("Audio Manager Invalid Action Warning: Attempt to stop background music without playing one before")
	else
		DEBRIS_SERVICE:AddItem(self.CurrentBackgroundMusic, BACKGROUND_MUSIC_FADE_INTERVAL / 2)
		TWEEN_SERVICE:Create(self.CurrentBackgroundMusic, TweenInfo.new(BACKGROUND_MUSIC_FADE_INTERVAL / 2), {Volume = 0}):Play()
		self.CurrentBackgroundMusic = nil
	end
end

function module:PlaySoundEffect(soundEffectId)
	local sound = self:GetAudioAssetFromId(soundEffectId, true)
	sound.Parent = SOUND_SERVICE_ASSET_FOLDER
	sound:Play()
    return sound
end

function module:PlaySoundEffectAtPosition(soundEffectId, position)
	local sound = self:GetAudioAssetFromId(soundEffectId, true)
	local soundAttachment = getSoundAttachment(position)
	soundAttachment.Parent = WORKSPACE_ASSET_FOLDER
	sound.Parent = soundAttachment
	sound:Play()
    return soundAttachment
end

function module:PlaySoundEffectOnInstance(soundEffectId, instance)
	local sound = self:GetAudioAssetFromId(soundEffectId, true)
	sound.Parent = instance
	sound:Play()
    return sound
end

return module.new()